const $=id=>document.getElementById(id);let records=[];
function el(tag,text){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;}
async function load(){try{const r=await fetch('/api/admin/leads?category='+$('category').value);if(!r.ok)throw Error('Administrator access unavailable. Sign in with an authorized account.');records=(await r.json()).records;render();}catch(e){$('admin-message').textContent=e.message;}}
function render(){const category=$('category').value;$('export').href='/api/admin/export?category='+category;$('export').textContent='Export full '+category+' list (CSV)';$('records').replaceChildren();
 const list=records.filter(r=>(!$('status').value||r.status===$('status').value)&&(!$('qualification').value||r.data.barberStatus===$('qualification').value)&&(!$('duplicates').checked||r.duplicate_count>0)&&(!$('experience').value||(r.data.experience!==''&&Number(r.data.experience)>=Number($('experience').value)))&&JSON.stringify(r).toLowerCase().includes($('search').value.toLowerCase()));
 $('count').textContent=list.length+' of '+records.length+' records';
 for(const r of list){const tr=el('tr');const person=el('td');person.append(el('strong',r.first_name+' '+(r.data.lastName||'')),el('div',r.email));tr.append(person);const detail=el('td'),details=el('details');details.append(el('summary','View application details'));for(const [k,v]of Object.entries(r.data))details.append(el('p',k+': '+v));detail.append(details);tr.append(detail);const status=el('td');if(category==='tester'){const select=el('select');select.setAttribute('aria-label','Status for '+r.email);for(const value of ['New','Under Review','Selected','Not Selected']){const o=el('option',value);select.append(o);}select.value=r.status;select.addEventListener('change',async()=>{select.disabled=true;try{const response=await fetch('/api/admin/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,status:select.value})});if(!response.ok)throw Error();r.status=select.value;$('admin-message').textContent='Status saved.';}catch{select.value=r.status;$('admin-message').textContent='Status was not saved. Try again.';}finally{select.disabled=false;}});status.append(select);}else status.textContent='Launch list';tr.append(status);tr.append(el('td',(r.consent?'Marketing consent given':'No marketing consent')+' · '+r.created_at));tr.append(el('td',r.duplicate_count));$('records').append(tr);}
 if(!list.length)$('admin-message').textContent='No records match the selected filters.';else $('admin-message').textContent='';
}
$('category').addEventListener('change',()=>{$('status').value='';$('qualification').value='';$('experience').value='';load();});for(const id of ['status','qualification','search','duplicates','experience'])$(id).addEventListener('input',render);load();
